ALTER TABLE atletas ADD COLUMN IF NOT EXISTS identity_id TEXT UNIQUE; CREATE UNIQUE INDEX IF NOT EXISTS resultados_unicos ON resultados(atleta_id,prova,data,dist); CREATE TABLE IF NOT EXISTS auditoria_homologacao(id BIGSERIAL PRIMARY KEY,resultado_id BIGINT NOT NULL REFERENCES resultados(id),administrador_id TEXT NOT NULL,status_anterior TEXT NOT NULL,status_novo TEXT NOT NULL,criado_em TIMESTAMPTZ NOT NULL DEFAULT now());